using System.Reflection;
using System.Text.Json;

namespace Practice.Tests
{
    public sealed record Example(string[] Input, string[] Expected);
    public sealed record Case(string Method, JsonElement[] Args, JsonElement Expected);
    public sealed record Exercise(string Id, string Name, string Class, string Title, string Kind, Example[] Examples, Case[] Cases, string? CheckHint = null);

    /// <summary>Test data, generated by tools/generator/gen.py into tools/exercises.json.</summary>
    public static class Data
    {
        static readonly Lazy<Dictionary<string, Exercise>> all = new(() =>
            JsonSerializer.Deserialize<List<Exercise>>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "exercises.json")),
                new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!.ToDictionary(e => e.Id));

        public static Exercise Get(string id) => all.Value[id];
        public static TheoryData<int> Cases(string id) => Numbers(Get(id).Cases.Length);
        public static TheoryData<int> Examples(string id) => Numbers(Get(id).Examples.Length);

        static TheoryData<int> Numbers(int count)
        {
            var data = new TheoryData<int>();
            for (int i = 1; i <= count; i++) data.Add(i);
            return data;
        }
    }

    /// <summary>Runs one example. Messages are written for a beginner: ./ex check prints them as they are.</summary>
    public static class Check
    {
        static readonly TimeSpan Timeout = TimeSpan.FromSeconds(5);

        /// <summary>Learner code (practice/) by default; CI points EXERCISE_ASSEMBLY at the reference solutions.</summary>
        static Assembly Target()
        {
            string? path = Environment.GetEnvironmentVariable("EXERCISE_ASSEMBLY");
            return string.IsNullOrEmpty(path) ? typeof(Practice.Program).Assembly : Assembly.LoadFrom(path);
        }

        static Type ExerciseClass(Exercise e)
        {
            Type? t = Target().GetType("Practice." + e.Class);
            if (t == null) Assert.Skip($"Not started yet. Start it with: ./ex start {e.Id}");
            return t!;
        }

        /// <summary>An exercise with its own checkHint (Parsons, debugging) replaces the generic hints with it.</summary>
        public static void Method(string id, int number)
        {
            Exercise e = Data.Get(id);
            if (string.IsNullOrEmpty(e.CheckHint)) { MethodCore(e, number); return; }
            try { MethodCore(e, number); }
            catch (Xunit.Sdk.FailException ex)
            {
                string kept = string.Join("\n", ex.Message.Split('\n').Where(l => !l.StartsWith("Hint:")));
                Assert.Fail(kept + "\nHint: " + e.CheckHint);
            }
        }

        static void MethodCore(Exercise e, int number)
        {
            Case c = e.Cases[number - 1];
            Type type = ExerciseClass(e);
            MethodInfo? m = type.GetMethod(c.Method, BindingFlags.Public | BindingFlags.Static);
            if (m == null) Assert.Fail($"I cannot find the method {c.Method} in {e.Class}. Did you rename it? Its name must stay {c.Method}.");
            ParameterInfo[] ps = m!.GetParameters();
            if (ps.Length != c.Args.Length) Assert.Fail($"{c.Method} must have {c.Args.Length} parameter(s), yours has {ps.Length}. Keep the first line of the method as it was.");
            object?[] args = ps.Select((p, i) => Convert(c.Args[i], p.ParameterType)).ToArray();
            string call = $"{c.Method}({string.Join(", ", args.Select(Runner.Show))})";

            if (m.ReturnType == typeof(void))
            {
                string expected = c.Expected.GetString()!;
                string printed = Capture("", () => m.Invoke(null, args));
                ComparePicture(call, expected, printed);
                return;
            }
            object? got = null;
            Capture("", () => got = m.Invoke(null, args));
            object? want = Convert(c.Expected, m.ReturnType);
            if (!Same(want, got))
            {
                string msg = $"{call} should return {Runner.Show(want)}, but your method returned {Runner.Show(got)}.";
                if (got is int or long && System.Convert.ToInt64(got) == 0 && !Equals(want, got)) msg += "\nHint: 0 is the starting value. Is your loop running at all? Is the result updated inside the loop?";
                else if (got is int or long && want is int or long) msg += "\nHint: trace this call on paper: one row per turn of the loop. Check the first and the last turn (< or <=? start at 0 or 1?).";
                if (got is string gs && want is string ws && gs.Trim() == ws.Trim()) msg += "\nHint: only spaces at the start or end are different.";
                if (got is string gs2 && want is string ws2 && gs2.ToLowerInvariant() == ws2.ToLowerInvariant() && gs2 != ws2) msg += "\nHint: only upper/lower case letters are different.";
                if (got is bool) msg += "\nHint: test this value by hand with a trace table. Which branch of your if does it take?";
                Assert.Fail(msg);
            }
        }

        public static void Example(string id, int number)
        {
            Exercise e = Data.Get(id);
            Example ex = e.Examples[number - 1];
            Type type = ExerciseClass(e);
            MethodInfo? run = type.GetMethod("Run", BindingFlags.Public | BindingFlags.Static, Type.EmptyTypes);
            if (run == null) Assert.Fail($"I cannot find Run() in {e.Class}. Keep the line `public static void Run()` as it was.");
            string printed = Capture(string.Join("\n", ex.Input) + "\n", () => run!.Invoke(null, null));
            string[] lines = printed.Replace("\r", "").Split('\n');
            int at = 0;
            foreach (string want in ex.Expected)
            {
                int found = -1;
                for (int i = at; i < lines.Length; i++)
                {
                    if (lines[i].TrimEnd().EndsWith(want.TrimEnd(), StringComparison.Ordinal)) { found = i; break; }
                }
                if (found == -1)
                {
                    string msg = $"With the input {Inputs(ex.Input)}, I expected a line ending with:\n    {want}\nYour program printed:\n{Box(printed)}";
                    if (lines.Any(l => l.Contains(want.Trim(), StringComparison.Ordinal))) msg += "\nHint: the text is there, but more text follows it on the same line. Use Console.WriteLine to end the line.";
                    else if (lines.Any(l => l.ToLowerInvariant().Contains(want.Trim().ToLowerInvariant()))) msg += "\nHint: only upper/lower case letters are different.";
                    else if (lines.Any(l => Squash(l).EndsWith(Squash(want), StringComparison.Ordinal))) msg += "\nHint: only the spaces are different.";
                    Assert.Fail(msg);
                }
                at = found + 1;
            }
        }

        static void ComparePicture(string call, string expected, string printed)
        {
            string[] want = expected.Replace("\r", "").TrimEnd('\n').Split('\n');
            string[] got = printed.Replace("\r", "").TrimEnd('\n').Split('\n');
            for (int i = 0; i < Math.Max(want.Length, got.Length); i++)
            {
                string w = i < want.Length ? want[i] : "(no line)";
                string g = i < got.Length ? got[i] : "(no line)";
                if (w.TrimEnd() != g.TrimEnd())
                {
                    string msg = $"{call} should print:\n{Box(expected)}\nYour method printed:\n{Box(printed)}\nThe first difference is on line {i + 1}: expected \"{w}\", got \"{g}\".";
                    if (printed.Trim().Length == 0) msg += "\nHint: nothing was printed yet. Use Console.Write(\"*\") for one character and Console.WriteLine() to end a row.";
                    else if (got.Length == 1 && want.Length > 1) msg += "\nHint: everything is on one line. Use Console.WriteLine() at the end of each row.";
                    else if (w.Trim() == g.Trim()) msg += "\nHint: only the spaces at the start of the line are different.";
                    Assert.Fail(msg);
                }
            }
        }

        /// <summary>Runs the learner's code with fake keyboard input, and returns what it printed.</summary>
        static string Capture(string input, Action action)
        {
            TextReader oldIn = Console.In;
            TextWriter oldOut = Console.Out;
            var output = new StringWriter();
            Console.SetIn(new StringReader(input));
            Console.SetOut(output);
            try
            {
                Task task = Task.Run(action);
                if (!task.Wait(Timeout))
                    Assert.Fail($"Your code was still running after {Timeout.TotalSeconds} seconds. Is there a loop that never stops? Check that its condition becomes false.");
            }
            catch (AggregateException ae) when (ae.InnerException is TargetInvocationException tie && tie.InnerException != null)
            {
                Exception inner = tie.InnerException;
                string what = inner switch
                {
                    ArgumentNullException => "your program tried to read more input than the example gives (Console.ReadLine() returned null). Does it stop at the right moment?",
                    IndexOutOfRangeException => "an index went outside the array or the text (IndexOutOfRangeException). Check the loop condition: < Length, not <= Length.",
                    DivideByZeroException => "a division by zero.",
                    FormatException => "int.Parse got something that is not a number (FormatException).",
                    _ => $"{inner.GetType().Name}: {inner.Message}",
                };
                Assert.Fail($"Your code crashed: {what}\nWhat it printed before the crash:\n{Box(output.ToString())}");
            }
            finally
            {
                Console.SetIn(oldIn);
                Console.SetOut(oldOut);
            }
            return output.ToString();
        }

        static object? Convert(JsonElement v, Type t)
        {
            if (t == typeof(int)) return v.GetInt32();
            if (t == typeof(long)) return v.GetInt64();
            if (t == typeof(double)) return v.GetDouble();
            if (t == typeof(bool)) return v.GetBoolean();
            if (t == typeof(string)) return v.GetString();
            if (t == typeof(char)) return v.GetString()![0];
            if (t == typeof(int[])) return v.EnumerateArray().Select(x => x.GetInt32()).ToArray();
            throw new NotSupportedException(t.Name);
        }

        static bool Same(object? a, object? b) => (a, b) switch
        {
            (double x, double y) => Math.Abs(x - y) < 1e-4,
            (int[] x, int[] y) => x.SequenceEqual(y),
            _ => Equals(a, b),
        };

        static string Inputs(string[] input) => input.Length == 0 ? "(no input)" : string.Join(", ", input.Select(i => i == "" ? "(empty line)" : i));
        static string Squash(string s) => s.Replace(" ", "");
        static string Box(string text)
        {
            string t = text.Replace("\r", "").TrimEnd('\n');
            return t.Length == 0 ? "    (nothing)" : string.Join("\n", t.Split('\n').Select(l => "    | " + l));
        }
    }
}
